export type FigmaIconName = keyof typeof icons;

/** A design icon at the size its className gives it (decorative: hidden from assistive tech). */
export function FigmaIcon({ name, ...props }: SVGProps<SVGSVGElement> & { name: FigmaIconName }) {
  const { viewBox, body } = icons[name];
  return (
    <svg viewBox={viewBox} fill="none" aria-hidden="true" focusable="false" {...props}>
      {body}
    </svg>
  );
}
